import{_ as r,o as l,c as t,ak as i}from"./chunks/framework.CMX7UUIo.js";const p=JSON.parse('{"title":"小麦的加工","description":"","frontmatter":{"title":"小麦的加工"},"headers":[],"relativePath":"crops/wheat/processing.md","filePath":"crops/wheat/processing.md"}'),e={name:"crops/wheat/processing.md"};function n(o,a,s,h,d,g){return l(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="小麦的加工" tabindex="-1">小麦的加工 <a class="header-anchor" href="#小麦的加工" aria-label="Permalink to “小麦的加工”">​</a></h1><p>小麦加工是将小麦除去杂质，经搭配、调节水分、破碎、剥刮胚乳、分级提纯、研磨筛理，生产出含麸屑甚少的各级小麦粉的过程。其加工过程是影响小麦面粉技术性能和最终产品质量的关键因素。</p><h2 id="进料和预清理" tabindex="-1">进料和预清理 <a class="header-anchor" href="#进料和预清理" aria-label="Permalink to “进料和预清理”">​</a></h2><p>小麦加工的第一道工序是<strong>进料和预清理</strong>，目的是去除原粮中的大杂质、轻杂和灰尘，为后续清理工序创造良好条件。</p><h3 id="毛麦接收" tabindex="-1">毛麦接收 <a class="header-anchor" href="#毛麦接收" aria-label="Permalink to “毛麦接收”">​</a></h3><p>小麦从各地运抵面粉厂后，首先进入接收系统。接收工序包括：</p><ul><li><strong>自动称重</strong>：记录入厂小麦的数量</li><li><strong>初检</strong>：检测水分、容重、杂质含量等基本指标</li><li><strong>暂存</strong>：根据品质分类存入毛麦仓</li></ul><h3 id="预清理" tabindex="-1">预清理 <a class="header-anchor" href="#预清理" aria-label="Permalink to “预清理”">​</a></h3><p>预清理主要去除小麦中的<strong>大杂质</strong>和<strong>轻杂</strong>：</p><ul><li><strong>筛选</strong>：使用振动筛或平面回转筛去除大于小麦的杂质（如秸秆、土块）</li><li><strong>风选</strong>：利用气流分离轻杂（如麦壳、灰尘）</li><li><strong>磁选</strong>：去除磁性金属杂质</li></ul><h2 id="清洗和调制" tabindex="-1">清洗和调制 <a class="header-anchor" href="#清洗和调制" aria-label="Permalink to “清洗和调制”">​</a></h2><p>清洗和调制是小麦制粉前最关键的准备工序，直接影响面粉质量和出粉率。</p><h3 id="湿法清理" tabindex="-1">湿法清理 <a class="header-anchor" href="#湿法清理" aria-label="Permalink to “湿法清理”">​</a></h3><p><strong>洗麦机</strong>是湿法清理的核心设备，主要功能：</p><ul><li>浸泡小麦，使麦粒表面杂质软化</li><li>去除并肩石（与小麦粒度相近的砂石）</li><li>调节小麦水分</li><li>杀灭部分微生物</li></ul><h3 id="干法清理" tabindex="-1">干法清理 <a class="header-anchor" href="#干法清理" aria-label="Permalink to “干法清理”">​</a></h3><ul><li><strong>打麦机</strong>：通过打击去除麦粒表面的尘土、微生物和嵌入的杂质</li><li><strong>精选机</strong>：根据籽粒长度差异去除荞子、野豌豆等异种粮粒</li><li><strong>刷麦机</strong>：清理麦沟中的杂质</li></ul><h3 id="水分调节" tabindex="-1">水分调节 <a class="header-anchor" href="#水分调节" aria-label="Permalink to “水分调节”">​</a></h3><p><strong>着水机</strong>用于精确控制小麦水分：</p><ul><li>根据小麦原始水分和目标面粉水分添加适量水</li><li>冬季水温一般控制在35-45°C，促进水分渗透</li><li>着水后小麦需静置6-8小时，使水分均匀渗透至麦粒内部</li></ul><h3 id="搭配" tabindex="-1">搭配 <a class="header-anchor" href="#搭配" aria-label="Permalink to “搭配”">​</a></h3><p>不同产地、品种的小麦品质差异较大，需要进行<strong>搭配</strong>：</p><ul><li>调节蛋白质含量，确保面粉质量稳定</li><li>平衡面筋质量和灰分含量</li><li>优化成本，提高经济效益</li></ul><h2 id="制粉" tabindex="-1">制粉 <a class="header-anchor" href="#制粉" aria-label="Permalink to “制粉”">​</a></h2><p>制粉是小麦加工的核心环节，通过物理方法将麦粒各部分分离并研磨成粉。</p><h3 id="清理流程" tabindex="-1">清理流程 <a class="header-anchor" href="#清理流程" aria-label="Permalink to “清理流程”">​</a></h3><ol><li><strong>皮磨系统</strong>：处理麸皮和胚乳的分离</li><li><strong>心磨系统</strong>：精细研磨胚乳，获取细白面粉</li><li><strong>渣磨系统</strong>：处理麦渣，进一步提取胚乳</li><li><strong>尾磨系统</strong>：处理麸皮末端物料，提取残留胚乳</li></ol><h3 id="主要设备" tabindex="-1">主要设备 <a class="header-anchor" href="#主要设备" aria-label="Permalink to “主要设备”">​</a></h3><table tabindex="0"><thead><tr><th>设备</th><th>功能</th></tr></thead><tbody><tr><td><strong>磨粉机</strong></td><td>利用磨辊的挤压和剪切作用将胚乳研磨成粉</td></tr><tr><td><strong>平筛</strong></td><td>筛分不同粒度的面粉和麸皮</td></tr><tr><td><strong>清粉机</strong></td><td>利用气流和筛分纯化麦渣，提高面粉质量</td></tr><tr><td><strong>打麸机</strong></td><td>分离粘附在麸皮上的面粉</td></tr></tbody></table><h3 id="研磨系统" tabindex="-1">研磨系统 <a class="header-anchor" href="#研磨系统" aria-label="Permalink to “研磨系统”">​</a></h3><p>现代制粉采用<strong>多道研磨</strong>工艺，通常包含：</p><ul><li>4-5道皮磨</li><li>6-8道心磨</li><li>2-3道渣磨</li><li>1-2道尾磨</li></ul><p>每道研磨后都需通过筛理分级，实现物料的合理分流。</p><h2 id="面粉后处理" tabindex="-1">面粉后处理 <a class="header-anchor" href="#面粉后处理" aria-label="Permalink to “面粉后处理”">​</a></h2><h3 id="面粉配制" tabindex="-1">面粉配制 <a class="header-anchor" href="#面粉配制" aria-label="Permalink to “面粉配制”">​</a></h3><p>根据不同用途要求，将不同系统生产的面粉进行<strong>精确配制</strong>：</p><ul><li>调整蛋白质含量和质量</li><li>控制灰分指标</li><li>优化白度和筋度</li></ul><h3 id="熟化" tabindex="-1">熟化 <a class="header-anchor" href="#熟化" aria-label="Permalink to “熟化”">​</a></h3><p>新磨制的面粉需要<strong>静置熟化</strong>：</p><ul><li>使面筋蛋白质充分氧化，改善面团流变特性</li><li>促进酶活性的稳定</li><li>改善面粉的烘焙性能</li></ul><p>熟化时间通常为1-3天，温度控制在20-25°C。</p><h3 id="存储" tabindex="-1">存储 <a class="header-anchor" href="#存储" aria-label="Permalink to “存储”">​</a></h3><p>面粉的存储条件要求：</p><ul><li><strong>温度</strong>：控制在20°C以下，防止虫害和霉变</li><li><strong>湿度</strong>：相对湿度不超过70%，防止结块</li><li><strong>通风</strong>：保持空气流通，避免异味吸附</li><li><strong>避光</strong>：防止光照引起色素氧化变色</li></ul><h3 id="包装" tabindex="-1">包装 <a class="header-anchor" href="#包装" aria-label="Permalink to “包装”">​</a></h3><p>根据不同市场需求进行<strong>分级包装</strong>：</p><ul><li>零售包装：1kg、2.5kg、5kg等小包装</li><li>批发包装：10kg、25kg编织袋</li><li>散装：直接配送至食品加工厂</li></ul><p>包装过程需严格控制<strong>金属检测</strong>和<strong>重量检验</strong>。</p><h2 id="副产品处理" tabindex="-1">副产品处理 <a class="header-anchor" href="#副产品处理" aria-label="Permalink to “副产品处理”">​</a></h2><p>小麦加工过程中会产生多种副产品：</p><ul><li><strong>麸皮</strong>：小麦的外层表皮，富含膳食纤维和B族维生素，主要用作饲料</li><li><strong>次粉</strong>：麸皮和面粉之间的过渡产品，可用于饲料或食品添加剂</li><li><strong>胚芽</strong>：小麦的胚胎部分，营养价值高，可提取胚芽油或用作食品原料</li></ul>',51)])])}const b=r(e,[["render",n]]);export{p as __pageData,b as default};
